@push('scripts')<script>$(function(){const base=@json(route('admin.reports.index',$report));const t=initializeDataTable({selector:'#report-table',url:base,filters:()=>({from_date:$('#report-from').val(),to_date:$('#report-to').val()}),columns:[{data:'DT_RowIndex',orderable:false,searchable:false},{data:'report_date'},{data:'reference'},{data:'party'},{data:'description'},{data:'debit'},{data:'credit'},{data:'amount'},{data:'status'}],order:[[1,'desc']]});$('#report-from,#report-to').on('change',()=>t.ajax.reload());$('#report-reset').on('click',()=>{$('#report-from,#report-to').val('');t.ajax.reload();});$('#report-pdf').on('click',()=>location.href=@json(route('admin.reports.pdf',$report))+'?from_date='+($('#report-from').val()||'')+'&to_date='+($('#report-to').val()||''));});</script>@endpush
